    time.sleep(0.4)
    data0, W0, H0 = shot.grab_printwindow(sw)
    if data0:
        shot.write_png(os.path.join(OUT, 'hover_0_clean.png'), W0, H0, data0)

    print('2) 先滚动（像用户那样先滚轮，再把鼠标移过去）')
    for _ in range(2):
        u32.PostMessageW(sw, WM_MOUSEWHEEL, (0xFF88 << 16) & 0xFFFFFFFF,
                         ((box_y & 0xFFFF) << 16) | (box_x & 0xFFFF))
        time.sleep(0.05)
    time.sleep(0.5)

    # 滚过之后，「停靠边」那行整体上移了 scroll 逻辑像素。
    # 「上」按钮的新位置 ≈ 原 y - scroll。这里直接在"原位置"上多试几个 y，
    # 看哪个 y 会把「上」点亮 —— 如果点亮发生在"未滚动的旧坐标"，就是命中没跟着滚。
    print('3) 逐个 y 试探：在哪一行移鼠标会让「上」亮起来')
    dpi2 = u32.GetDpiForWindow(sw) / 96.0
    for probe_y in (150, 175, 195, 215, 240, 265, 285, 310):
        py = sr.top + int(round(probe_y * dpi2))
        u32.SetCursorPos(box_x, py)
        time.sleep(0.35)
        dd, WW, HH = shot.grab_printwindow(sw)
        if dd:
            shot.write_png(os.path.join(OUT, 'hover_probe_y%d.png' % probe_y), WW, HH, dd)
        print('   y=%d 已截图' % probe_y)

